    def onbellekle(ttl=None, saat=time.monotonic):
        def dekorator(f):
            isabet = iska = 0

            # Her fonksiyon için ayrı bir sözlük (cache)
            func_cache = {}

            @functools.wraps(f)
            def sarmal(*args, **kwargs):
                nonlocal isabet, iska

                # Hashlenemeyen argüman kontrolü (basitçe try-except ile yapılabilir)
                # Ancak docstring'e göre hashlenemeyenler için direkt çalıştırılmalı.
                # Argümanları (args, sorted_kwargs) şeklinde bir tuple yaparak anahtar oluşturacağız.

                # Önce isimli argümanları sıralı bir şekilde tuple'a çevirelim
                sorted_kwargs = tuple(sorted(kwargs.items()))
                anahtar_parcalari = (args, sorted_kwargs)

                try:
                    hash(anahtar_parcalari)
                    anahtar = anahtar_parcalari
                except TypeError:
                    # Hashlenemeyen argüman varsa, cache mekanizmasını atla
                    iska += 1
                    return f(*args, **kwargs)

                if anahtar in func_cache:
                    deger, zaman = func_cache[anahtar]
                    if ttl is None or saat() - zaman >= ttl: # docstring: tam ttl anında hâlâ geçerlidir
                        # NOT: docstring "ttl saniye geçtikten SONRA geçersiz olur" diyor.
                        # Yani saat() - zaman > ttl ise geçersiz. 
                        # Eğer saat() - zaman <= ttl ise geçerlidir.
                        # Mevcut kodda 'saat() - zaman > ttl' ise geçerli diyordu (yanlış), 
                        # ama docstring'e göre 'saat() - zaman > ttl' ise geçersiz (yeni çalışmalı).
                        # Doğru mantık: Eğer saat() - zaman <= ttl ise değer geçerlidir.
                        pass # aşağıda kontrol edeceğiz

                    if ttl is None or (saat() - zaman <= ttl):
                        isabet += 1
                        return deger

                # Cache'te yoksa veya geçersizse
                iska += 1
                deger = f(*args, **kwargs)
                func_cache[anahtar] = (deger, saat())
                return deger

            def temizle():
                func_cache.clear()

            def bilgi():
                return {"isabet": isabet, "iska": iska}

            sarmal.temizle = temizle
            sarmal.bilgi = bilgi
            return sarmal
        return dekorator
    return onbellekle

